CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sites (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, description TEXT);
CREATE TABLE IF NOT EXISTS loggers (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, name TEXT NOT NULL, model TEXT, serial_number TEXT, role TEXT DEFAULT 'water_level', depth_offset_cm DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS logger_files (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, logger_id INTEGER NOT NULL REFERENCES loggers(id) ON DELETE CASCADE, timestamp TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, file TEXT NOT NULL, type TEXT, measurement_kind TEXT, measurement_unit TEXT, UNIQUE (logger_id, file));
CREATE TABLE IF NOT EXISTS logger_data (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, logger_id INTEGER NOT NULL REFERENCES loggers(id) ON DELETE CASCADE, logger_file_id INTEGER NOT NULL REFERENCES logger_files(id) ON DELETE CASCADE, timestamp TIMESTAMP WITHOUT TIME ZONE NOT NULL, level_m DOUBLE PRECISION, imported_value DOUBLE PRECISION, imported_unit TEXT, imported_kind TEXT, baro_corrected_m DOUBLE PRECISION, correction_run_id INTEGER, temp_c DOUBLE PRECISION, sal_psu DOUBLE PRECISION, ec_us DOUBLE PRECISION, UNIQUE (logger_id, timestamp));
CREATE TABLE IF NOT EXISTS logger_events (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, logger_id INTEGER NOT NULL REFERENCES loggers(id) ON DELETE CASCADE, timestamp TIMESTAMP WITHOUT TIME ZONE NOT NULL, event_type TEXT NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS manual_readings (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, timestamp TIMESTAMP WITHOUT TIME ZONE NOT NULL, value DOUBLE PRECISION NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS corrected_data (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, logger_data_id INTEGER NOT NULL REFERENCES logger_data(id) ON DELETE CASCADE, timestamp TIMESTAMP WITHOUT TIME ZONE NOT NULL, corrected_value DOUBLE PRECISION NOT NULL, temp_c DOUBLE PRECISION, sal_psu DOUBLE PRECISION, ec_us DOUBLE PRECISION, UNIQUE (site_id, timestamp));
CREATE TABLE IF NOT EXISTS baro_assignments (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, scope TEXT NOT NULL, scope_id INTEGER NOT NULL, barologger_id INTEGER NOT NULL REFERENCES loggers(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(scope, scope_id));
CREATE TABLE IF NOT EXISTS correction_runs (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, logger_id INTEGER REFERENCES loggers(id) ON DELETE SET NULL, barologger_id INTEGER NOT NULL REFERENCES loggers(id) ON DELETE CASCADE, method TEXT NOT NULL, density_mode TEXT NOT NULL, density_kg_m3 DOUBLE PRECISION NOT NULL, match_mode TEXT NOT NULL, max_gap_seconds INTEGER NOT NULL, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_logger_data_logger_file_id ON logger_data(logger_file_id);
CREATE INDEX IF NOT EXISTS idx_corrected_data_site_id ON corrected_data(site_id);
CREATE INDEX IF NOT EXISTS idx_corrected_data_logger_data_id ON corrected_data(logger_data_id);
INSERT INTO schema_migrations(version) VALUES (1) ON CONFLICT (version) DO NOTHING;
